nodes/delete-middle-node.text:
import { component$, $, noSerialize, useSignal, useVisibleTask$, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { SnapController } from '@grafloria/element';
import { markReady } from '../ready';

const nodes = [
  { id: 'a', position: { x: 60,  y: 120 }, size: { width: 160, height: 80 }, label: 'A' },
  { id: 'b', position: { x: 340, y: 120 }, size: { width: 160, height: 80 }, label: 'B (middle)' },
  { id: 'c', position: { x: 620, y: 120 }, size: { width: 160, height: 80 }, label: 'C' },
];
const edges = [
  { id: 'ab', source: 'a', target: 'b' },
  { id: 'bc', source: 'b', target: 'c' },
];

/** Wire Delete/Backspace to a healing delete. Module level so the onInit$ QRL
 *  may call it; returns the disposer that unhooks the key listener. */
function installHealingDelete(instance: DiagramInstance): () => void {
  const model = instance.getModel() as any;
  const eng = instance.getEngine() as any;
  const snap = new SnapController();

  const healDelete = async (id: string) => {
    const links = model.getLinks();
    const incomers = [...new Set(links.filter((l: any) => l.targetNodeId === id).map((l: any) => l.sourceNodeId))];
    const outgoers = [...new Set(links.filter((l: any) => l.sourceNodeId === id).map((l: any) => l.targetNodeId))];
    await eng.removeNode(id);
    for (const s of incomers as string[]) for (const t of outgoers as string[]) {
      if (s === t) continue;
      const sn = model.getNode(s), tn = model.getNode(t);
      if (!sn || !tn) continue;
      if (model.getLinks().some((l: any) => l.sourceNodeId === s && l.targetNodeId === t)) continue;
      const candidate = {
        sourcePort: sn.getPortBySide('right') ?? sn.getPorts()[0],
        targetPort: tn.getPortBySide('left') ?? tn.getPorts()[0],
        sourceNodeId: s, targetNodeId: t, distance: 0,
      };
      eng.commandManager.execute(snap.buildProximityLinkCommand(candidate));
    }
    instance.renderNow();
  };

  const onKey = (e: KeyboardEvent) => {
    if (e.key !== 'Delete' && e.key !== 'Backspace') return;
    const sel = model.getSelectedNodes ? model.getSelectedNodes() : [];
    if (!sel.length) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    (async () => { for (const n of sel) await healDelete(n.id); })();
  };
  window.addEventListener('keydown', onKey, true);
  return () => window.removeEventListener('keydown', onKey, true);
}

/** Select B and press Delete: the chain heals — its two edges cascade away and
 *  a fresh A→C bridge is drawn through the same command stack a hand-drawn wire
 *  uses (so it is real and undoable). */
export default component$(() => {
  // The key listener lives on window: unhook it when the demo unmounts.
  const dispose = useSignal<NoSerialize<() => void>>();
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => cleanup(() => dispose.value?.()), { strategy: 'document-ready' });

  return (
    <div style={{ height: '100vh' }}>
      <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} onInit$={$((instance: DiagramInstance) => {
        dispose.value = noSerialize(installHealingDelete(instance));
        markReady();
      })} />
    </div>
  );
});

nodes/drag-handle.text:
import { component$, $ } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance, type EdgeSpec } from '@grafloria/qwik';
import { markReady } from '../ready';

const nodes = [
  { id: 'win',  position: { x: 300, y: 200 }, size: { width: 240, height: 120 }, label: 'window body' },
  { id: 'grip', position: { x: 300, y: 200 }, size: { width: 240, height: 28 },  label: '⠿ title bar (drag me)' },
];
const edges: EdgeSpec[] = [];

/** A designated grip drags its parent — and ONLY the grip: the body still
 *  selects but no longer drags. The grip is made a drag-handle child INSIDE the
 *  parent's top strip through the live model. */
export default component$(() => (
  <div style={{ height: '100vh' }}>
    <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} onInit$={$((instance: DiagramInstance) => {
      const grip = instance.getModel().getNode('grip');
      if (grip) {
        grip.setParent('win');
        grip.setPosition(0, 0);               // local → covers the parent's top 28px
        grip.setBehavior({ dragHandler: { isDragHandler: true } });
        instance.renderNow();
      }
      markReady();
    })} />
  </div>
));

nodes/easy-connect.text:
import { component$, $, noSerialize, useSignal, useVisibleTask$, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance, type EdgeSpec } from '@grafloria/qwik';
import { registerTool, SnapController } from '@grafloria/element';
import { markReady } from '../ready';

const nodes = [
  { id: 'a', position: { x: 100, y: 150 }, size: { width: 200, height: 120 }, label: 'A · press anywhere' },
  { id: 'b', position: { x: 560, y: 150 }, size: { width: 200, height: 120 }, label: 'B · release anywhere' },
];
const edges: EdgeSpec[] = [];

/** Register the whole-node connect tool. Module level so the onInit$ QRL may
 *  call it; returns registerTool's disposer. */
function installEasyConnect(instance: DiagramInstance): () => void {
  const model = instance.getModel();
  const engine = instance.getEngine() as any;
  const snap = new SnapController();
  let src: any = null;
  return registerTool({
    id: 'demo-easy-connect',
    priority: 10,
    hitTest: (_e: any, hit: any) => !!hit.node,
    onPointerDown: (_e: any, hit: any) => { src = hit.node; },
    onPointerUp: (e: any) => {
      if (!src) return;
      const tgt = (model as any).getNodeAtPosition(e.world.x, e.world.y);
      if (tgt && tgt.id !== src.id) {
        const candidate = {
          sourcePort: src.getPortBySide('right') ?? src.getPorts()[0],
          targetPort: tgt.getPortBySide('left') ?? tgt.getPorts()[0],
          sourceNodeId: src.id, targetNodeId: tgt.id, distance: 0,
        };
        engine.commandManager.execute(snap.buildProximityLinkCommand(candidate));
      }
      src = null;
    },
    onCancel: () => { src = null; },
  } as any);
}

/** The whole node is a connection handle: press anywhere on one node, release
 *  anywhere on another, and they wire up — no tiny port to aim at. Wired through
 *  the public registerTool seam, committing a real link via the link command. */
export default component$(() => {
  // Tools are a global registry: unregister ours when the demo unmounts, or it
  // would keep hijacking node presses on whatever demo the router shows next.
  const dispose = useSignal<NoSerialize<() => void>>();
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => cleanup(() => dispose.value?.()), { strategy: 'document-ready' });

  return (
    <div style={{ height: '100vh' }}>
      <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} onInit$={$((instance: DiagramInstance) => {
        dispose.value = noSerialize(installEasyConnect(instance));
        markReady();
      })} />
    </div>
  );
});

nodes/intersections.text:
import { component$, $ } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance, type EdgeSpec } from '@grafloria/qwik';
import { createDiagramApi } from '@grafloria/element';
import { markReady } from '../ready';

const nodes = [
  { id: 'a', position: { x: 120, y: 140 }, size: { width: 180, height: 110 }, label: 'A · drag me' },
  { id: 'b', position: { x: 460, y: 140 }, size: { width: 180, height: 110 }, label: 'B' },
  { id: 'c', position: { x: 800, y: 140 }, size: { width: 180, height: 110 }, label: 'C' },
  // Small enough to fit ENTIRELY inside another node (overlap vs containment).
  { id: 's', position: { x: 150, y: 430 }, size: { width: 60, height: 60 }, label: 'S' },
];
const edges: EdgeSpec[] = [];

// The shared highlight style. Identity (===) marks a highlight as ours.
const HILITE = { type: 'rect', fill: '#fecaca', stroke: '#dc2626' };
const rectOf = (n: any) => ({ x: n.position.x, y: n.position.y, width: n.size.width, height: n.size.height });

/** Light up, live, every node the moved one overlaps. Module level so the
 *  onInit$ QRL may call it. */
function installIntersections(instance: DiagramInstance): void {
  const model = instance.getModel() as any;
  const api = createDiagramApi(instance as any) as any;

  const hits = (id: string) => api
    .getIntersectingNodes(rectOf(model.getNode(id)))
    .filter((o: any) => o.id !== id)
    .map((o: any) => o.id);

  const relight = (movedId: string) => {
    const moved = model.getNode(movedId);
    if (!moved) return;
    const lit = hits(movedId);
    for (const n of model.getNodes()) {
      const want = lit.includes(n.id);
      const has = n.getMetadata('shape') === HILITE;
      if (want && !has) n.setMetadata('shape', HILITE);
      else if (!want && has) n.setMetadata('shape', undefined);
    }
  };
  model.on('node:moved', ({ nodeId }: any) => relight(nodeId));
}

/** Drag a node and every node it overlaps lights up red, live — the public
 *  createDiagramApi(...).getIntersectingNodes wrapper on each move. */
export default component$(() => (
  <div style={{ height: '100vh' }}>
    <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} onInit$={$((instance: DiagramInstance) => {
      installIntersections(instance);
      markReady();
    })} />
  </div>
));

nodes/node-position-animation.text:
import { component$, $, noSerialize, useSignal, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { markReady } from '../ready';

const IDS = Array.from({ length: 8 }, (_, i) => `n${i}`);
const SIZE = { width: 96, height: 40 };
const HX = SIZE.width / 2, HY = SIZE.height / 2;
const CX = 600, CY = 285;

type Layout = Record<string, { x: number; y: number }>;

// Three target layouts as {id: {x,y}} of the node's top-left.
function circleLayout() { const o: Layout = {}; IDS.forEach((id, i) => { const a = (i / IDS.length) * 2 * Math.PI - Math.PI / 2; o[id] = { x: CX + 250 * Math.cos(a) - HX, y: CY + 205 * Math.sin(a) - HY }; }); return o; }
function gridLayout()   { const o: Layout = {}; IDS.forEach((id, i) => { const c = i % 4, r = (i / 4) | 0; o[id] = { x: (315 + c * 190) - HX, y: (160 + r * 250) - HY }; }); return o; }
function rowLayout()    { const o: Layout = {}; IDS.forEach((id, i) => { o[id] = { x: (90 + i * 145) - HX, y: CY - HY }; }); return o; }

const LAYOUTS: Record<string, Layout> = { grid: gridLayout(), circle: circleLayout(), row: rowLayout() };
const ORDER = ['grid', 'circle', 'row'];
const EDGES = IDS.map((id, i) => ({ id: `e${i}`, source: id, target: IDS[(i + 1) % IDS.length]! })); // a ring
const NODES = IDS.map((id) => ({ id, position: { ...LAYOUTS.grid![id]! }, size: SIZE, label: id.toUpperCase() }));

const easeOutCubic = (t: number) => 1 - Math.pow(1 - t, 3);

/** Tween every node to its target on an ease-out curve. Module level so the
 *  onClick$ QRL may call it (a helper inside component$ could not be). */
function tweenTo(instance: DiagramInstance, targets: Layout, duration = 900): Promise<void> {
  return new Promise<void>((resolve) => {
    const model = instance.getModel() as any;
    const starts: Layout = {};
    for (const id of Object.keys(targets)) { const p = model.getNode(id).position; starts[id] = { x: p.x, y: p.y }; }
    const t0 = performance.now();
    const frame = (now: number) => {
      const raw = Math.min(1, (now - t0) / duration);
      const k = easeOutCubic(raw);
      instance.batchUpdate((m: any) => {
        for (const id of Object.keys(targets)) {
          const s = starts[id]!, t = targets[id]!;
          m.getNode(id).setPosition(s.x + (t.x - s.x) * k, s.y + (t.y - s.y) * k);
        }
      });
      instance.renderNow();
      if (raw < 1) requestAnimationFrame(frame); else resolve();
    };
    requestAnimationFrame(frame);
  });
}

/** Eight nodes tween between layouts — grid · ring · row — by writing
 *  node.position every frame on an ease-out curve (pure userland). */
export default component$(() => {
  const instance = useSignal<NoSerialize<DiagramInstance>>();
  const busy = useSignal(false);
  const current = useSignal('grid');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <div style={{ display: 'flex', gap: '16px', alignItems: 'center', padding: '10px 24px',
        borderBottom: '1px solid rgba(127,127,127,.25)', font: '12px system-ui, sans-serif' }}>
        <button type="button"
          onClick$={async () => {
            const api = instance.value;
            if (busy.value || !api) return;
            busy.value = true;
            const next = ORDER[(ORDER.indexOf(current.value) + 1) % ORDER.length]!;
            current.value = next;
            await tweenTo(api, LAYOUTS[next]!);
            busy.value = false;
          }}
          style={{ font: '12px system-ui, sans-serif', padding: '4px 12px', border: '1px solid rgba(127,127,127,.5)', borderRadius: '6px', background: 'transparent', color: 'inherit', cursor: 'pointer' }}>
          ▶ shuffle layout
        </button>
        <span style={{ opacity: 0.7 }}>layout: {current.value}</span>
      </div>
      <div style={{ flex: '1' }}>
        <GrafloriaFlow defaultNodes={NODES} defaultEdges={EDGES}
          onInit$={$((api: DiagramInstance) => { instance.value = noSerialize(api); markReady(); })} />
      </div>
    </div>
  );
});

