import { component$, $, noSerialize, useSignal, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { markReady } from '../ready';

const nodes = [
  { id: 'start', position: { x: 80, y: 60 },  size: { width: 140, height: 60 }, data: { label: 'Start' } },
  { id: 'work',  position: { x: 320, y: 60 }, size: { width: 140, height: 60 }, data: { label: 'Work' } },
  { id: 'done',  position: { x: 560, y: 60 }, size: { width: 140, height: 60 }, data: { label: 'Done' } },
];
const edges = [
  { id: 'e1', source: 'start', target: 'work' },
  { id: 'e2', source: 'work', target: 'done' },
];

/** Diagram-as-text: exportText() writes Mermaid-style text from the live
 *  canvas; loadText() reconciles edited text back INTO the same instance —
 *  positions survive through the lossless sidecar. */
export default component$(() => {
  const instance = useSignal<NoSerialize<DiagramInstance>>();
  const text = useSignal('');
  return (
    <div style={{ display: 'flex', height: '100vh' }}>
      <GrafloriaFlow
        defaultNodes={nodes}
        defaultEdges={edges}
        style={{ flex: '1' }}
        onInit$={$((api: DiagramInstance) => {
          instance.value = noSerialize(api);
          text.value = api.exportText();
          markReady();
        })}
      />
      <div style={{ width: '340px', borderLeft: '1px solid #E3E7F2', display: 'flex', flexDirection: 'column', padding: '10px', gap: '8px' }}>
        <div style={{ display: 'flex', gap: '8px' }}>
          <button onClick$={() => { if (instance.value) text.value = instance.value.exportText(); }}
            style={{ padding: '6px 14px', borderRadius: '7px', border: '0', background: '#3B52D9', color: '#fff', fontWeight: '600', cursor: 'pointer' }}>⇢ Export</button>
          <button onClick$={() => { instance.value?.loadText(text.value); }}
            style={{ padding: '6px 14px', borderRadius: '7px', border: '1px solid #94A5F0', background: '#EEF1FE', color: '#3B52D9', fontWeight: '600', cursor: 'pointer' }}>⇠ Load</button>
        </div>
        <textarea value={text.value} onInput$={(_, el) => { text.value = el.value; }}
          style={{ flex: '1', font: '12.5px/1.6 ui-monospace, Menlo, monospace', border: '1px solid #E3E7F2', borderRadius: '8px', padding: '10px', resize: 'none' }} />
      </div>
    </div>
  );
});

interaction/computing-flows.text:
import { component$, $, noSerialize, useSignal, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { markReady } from '../ready';

const nodes = [
  { id: 'in',  position: { x: 40,  y: 120 }, size: { width: 120, height: 56 }, label: 'input',
    ports: [{ id: 'in.out', side: 'right', type: 'output', dataType: 'number' }], data: { value: 2 } },
  { id: 'mul', position: { x: 240, y: 120 }, size: { width: 120, height: 56 }, label: '× 3',
    ports: [{ id: 'mul.in', side: 'left', type: 'input', dataType: 'number' },
            { id: 'mul.out', side: 'right', type: 'output', dataType: 'number' }], data: { op: 'mul', k: 3, value: 0 } },
  { id: 'add', position: { x: 440, y: 120 }, size: { width: 120, height: 56 }, label: '+ 10',
    ports: [{ id: 'add.in', side: 'left', type: 'input', dataType: 'number' },
            { id: 'add.out', side: 'right', type: 'output', dataType: 'number' }], data: { op: 'add', k: 10, value: 0 } },
  { id: 'out', position: { x: 640, y: 120 }, size: { width: 120, height: 56 }, label: 'sink',
    ports: [{ id: 'out.in', side: 'left', type: 'input', dataType: 'number' }], data: { op: 'sink', value: 0 } },
] as never[];
const edges = [
  { id: 'l1', source: 'in',  target: 'mul', sourceHandle: 'in.out',  targetHandle: 'mul.in' },
  { id: 'l2', source: 'mul', target: 'add', sourceHandle: 'mul.out', targetHandle: 'add.in' },
  { id: 'l3', source: 'add', target: 'out', sourceHandle: 'add.out', targetHandle: 'out.in' },
];

/* eslint-disable @typescript-eslint/no-explicit-any */
/** Push the values down the REAL link topology, repaint, and return the
 *  readout. Module level so every Qwik handler can call it. */
function propagate(api: DiagramInstance): string {
  const model = api.getModel() as any;
  const order = ['in', 'mul', 'add', 'out'];
  const incoming = (nodeId: string) => model.getLinks().filter((l: any) => l.targetNodeId === nodeId);
  for (const id of order) {
    const node = model.getNode(id);
    if (id === 'in') continue;
    const feeds = incoming(id);
    const input = feeds.length ? (model.getNode(feeds[0].sourceNodeId)?.data.value ?? 0) : null;
    if (input === null) continue;
    const d = node.data;
    d.value = d.op === 'mul' ? input * d.k : d.op === 'add' ? input + d.k : input;
  }
  api.renderNow();
  const v = (id: string) => model.getNode(id).data.value;
  return `→  ×3=${v('mul')}  →  +10=${v('add')}  →  sink=${v('out')}`;
}

/** Data flowing through typed ports: type a value and every downstream node
 *  recomputes LIVE along the real link topology. Grafloria owns the graph and
 *  fires the change events; the app owns the arithmetic. */
export default component$(() => {
  const inst = useSignal<NoSerialize<DiagramInstance>>();
  const formula = useSignal('');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <div style={{ padding: '8px 24px', font: '12px/1.5 ui-monospace, monospace', opacity: '0.9',
        borderBottom: '1px solid rgba(127,127,127,.25)', display: 'flex', alignItems: 'center', gap: '14px', flexWrap: 'wrap' }}>
        <label style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}>input
          <input type="number" step={1} value={2}
            style={{ width: '74px', font: 'inherit', padding: '2px 6px', border: '1px solid rgba(127,127,127,.5)', borderRadius: '4px', background: 'transparent', color: 'inherit' }}
            onInput$={(_, el) => {
              const api = inst.value;
              if (!api) return;
              const n = Number(el.value);
              (api.getModel() as any).getNode('in').data.value = Number.isFinite(n) ? n : 0;
              formula.value = propagate(api);
            }} />
        </label>
        <span style={{ whiteSpace: 'pre' }}>{formula.value}</span>
      </div>
      <div style={{ flex: '1' }}>
        <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} onInit$={$((instance: DiagramInstance) => {
          inst.value = noSerialize(instance);
          const model = instance.getModel() as any;
          model.on('link:added', () => { formula.value = propagate(instance); });
          model.on('link:removed', () => { formula.value = propagate(instance); });
          formula.value = propagate(instance);
          markReady();
        })} />
      </div>
    </div>
  );
});

interaction/connection-events.text:
import { component$, $, noSerialize, useSignal, useVisibleTask$, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { markReady } from '../ready';

/* eslint-disable @typescript-eslint/no-explicit-any */
const nodes = [
  { id: 'src', position: { x: 80,  y: 70 }, size: { width: 150, height: 60 }, label: 'source',
    ports: [{ id: 'src.out', side: 'right', type: 'output' }] },
  { id: 'dst', position: { x: 430, y: 70 }, size: { width: 150, height: 60 }, label: 'target',
    ports: [{ id: 'dst.in', side: 'left', type: 'input' }] },
] as never[];

const EVENTS: [string, (p: any) => string][] = [
  ['connection:start',      (p) => p?.sourcePort?.id ?? '?'],
  ['connection:update',     (p) => `${p?.targetPort?.id ?? '(none)'} ${p?.isValid ? 'ok' : 'no'}`],
  ['connection:port-enter', (p) => `${p?.port?.id ?? '?'} ${p?.isValid ? 'ok' : '✗ ' + (p?.rejectionReason ?? '')}`],
  ['connection:port-leave', (p) => p?.port?.id ?? '?'],
  ['connection:complete',   (p) => `${p?.sourcePortId ?? '?'} → ${p?.targetPortId ?? '?'}`],
  ['connection:cancel',     (p) => `${p?.sourcePort?.id ?? '?'} (abandoned / refused)`],
];

interface Row { key: number; name: string; summary: string }

/** A live log of the connection lifecycle the engine fires as you drag a wire —
 *  start, per-move update, port enter/leave, then complete or cancel. */
export default component$(() => {
  const rows = useSignal<Row[]>([]);
  const disposers = useSignal<NoSerialize<Array<() => void>>>();

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    cleanup(() => disposers.value?.forEach((d) => d?.()));
  }, { strategy: 'document-ready' });

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <div style={{ padding: '8px 24px 10px', borderBottom: '1px solid rgba(127,127,127,.25)', font: '12px/1.4 ui-monospace, monospace' }}>
        <div style={{ height: '88px', overflowY: 'auto', whiteSpace: 'pre', opacity: '0.9' }}>
          {rows.value.length === 0
            ? <span class="empty" style={{ opacity: '0.5' }}>drag from the source&apos;s right port to see the connection lifecycle fire…</span>
            : rows.value.map((r) => (
              <div class="row" key={r.key}>
                <span style={{ display: 'inline-block', minWidth: '168px', fontWeight: '600' }}>{r.name}</span>
                <span>{r.summary}</span>
              </div>
            ))}
        </div>
      </div>
      <div style={{ flex: '1' }}>
        <GrafloriaFlow defaultNodes={nodes} defaultEdges={[]} onInit$={$((instance: DiagramInstance) => {
          const engine = instance.getEngine() as any;
          const summaryOf = new Map(EVENTS);
          let seq = 0;
          const logRow = (name: string, payload: any) => {
            const summary = (summaryOf.get(name) || (() => ''))(payload);
            rows.value = [{ key: ++seq, name, summary }, ...rows.value].slice(0, 12);
          };
          disposers.value = noSerialize(EVENTS.map(([name]) => engine.eventBus.on(name, (payload: any) => logRow(name, payload))));
          markReady();
        })} />
      </div>
    </div>
  );
});

interaction/context-menu.text:
import { component$, $, noSerialize, useSignal, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { markReady } from '../ready';

const nodes = [
  { id: 'a', position: { x: 120, y: 120 }, size: { width: 120, height: 48 }, label: 'Alpha' },
  { id: 'b', position: { x: 380, y: 120 }, size: { width: 120, height: 48 }, label: 'Beta' },
];
const edges = [{ id: 'e', source: 'a', target: 'b' }];

/* eslint-disable @typescript-eslint/no-explicit-any */
/** Every menu item mutates the model it names. */
async function act(api: DiagramInstance, id: string, action: string): Promise<void> {
  const model = api.getModel() as any;
  const engine = api.getEngine() as any;
  if (action === 'rename') model.getNode(id).setMetadata('label', 'RENAMED');
  if (action === 'delete') model.removeNode(id);
  if (action === 'duplicate') {
    const src = model.getNode(id);
    const copy = await engine.addNode({ type: 'rect', position: { x: src.position.x + 30, y: src.position.y + 60 }, size: { ...src.size } });
    copy.setMetadata('label', (src.getMetadata('label') ?? '') + ' copy');
  }
  api.renderNow();
}

const btn = { display: 'block', width: '100%', textAlign: 'left' as const, padding: '7px 10px',
  border: '0', background: 'transparent', color: 'inherit', borderRadius: '5px', cursor: 'pointer' };

/** Right-click a node for Rename / Duplicate / Delete — driven by a real
 *  contextmenu event, and every item actually mutates the model it names. */
export default component$(() => {
  const wrap = useSignal<HTMLElement>();
  const menuEl = useSignal<HTMLElement>();
  const inst = useSignal<NoSerialize<DiagramInstance>>();
  const open = useSignal(false);
  const pos = useSignal({ x: 0, y: 0 });
  const target = useSignal<string | null>(null);

  const choose = $(async (action: string) => {
    const api = inst.value;
    if (api && target.value) await act(api, target.value, action);
    open.value = false;
  });

  return (
    <div ref={wrap} style={{ height: '100vh', position: 'relative' }}>
      <div ref={menuEl} style={{ position: 'absolute', zIndex: '10', minWidth: '160px', background: 'var(--mbg,#1a1a1a)',
        color: 'inherit', border: '1px solid rgba(127,127,127,.35)', borderRadius: '8px', boxShadow: '0 8px 30px rgba(0,0,0,.18)',
        padding: '4px', display: open.value ? 'block' : 'none', font: '13px system-ui, sans-serif',
        left: `${pos.value.x}px`, top: `${pos.value.y}px` }} class={open.value ? 'open' : ''}>
        <button data-act="rename" style={btn} onClick$={() => choose('rename')}>Rename</button>
        <button data-act="duplicate" style={btn} onClick$={() => choose('duplicate')}>Duplicate</button>
        <button data-act="delete" style={btn} onClick$={() => choose('delete')}>Delete</button>
      </div>
      <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} onInit$={$((instance: DiagramInstance) => {
        inst.value = noSerialize(instance);
        const host = wrap.value!;
        // preventDefault must run synchronously and only over a node, so the
        // contextmenu listener is a plain DOM listener rather than onContextMenu$.
        host.addEventListener('contextmenu', (e) => {
          const el = (e.target as HTMLElement).closest('[data-node-id]');
          if (!el) return;
          e.preventDefault();
          target.value = el.getAttribute('data-node-id');
          const rect = host.getBoundingClientRect();
          pos.value = { x: e.clientX - rect.left, y: e.clientY - rect.top };
          open.value = true;
        });
        document.addEventListener('pointerdown', (e) => {
          if (!menuEl.value?.contains(e.target as Node)) open.value = false;
        });
        document.addEventListener('keydown', (e) => {
          if (e.key === 'Escape') open.value = false;
        });
        markReady();
      })} />
    </div>
  );
});

interaction/contextual-zoom.text:
import { component$, $, noSerialize, useSignal, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance, type EdgeSpec } from '@grafloria/qwik';
import { markReady } from '../ready';

const nodes = Array.from({ length: 12 }, (_, i) => ({
  id: `n${i}`, position: { x: (i % 4) * 200, y: Math.floor(i / 4) * 140 },
  size: { width: 150, height: 70 }, label: `Node ${i}`,
}));
const edges: EdgeSpec[] = Array.from({ length: 11 }, (_, i) => ({ id: `e${i}`, source: `n${i}`, target: `n${i + 1}`, type: 'direct' }));

/* eslint-disable @typescript-eslint/no-explicit-any */
/** Zoom to `z`, repaint, and report the tier the renderer chose. */
function tierAt(api: DiagramInstance, wrap: HTMLElement | undefined, z: number): string {
  const a = api as any;
  a.viewport.setZoom(z);
  a.renderNow();
  const tier = a.getQualityState().tier;
  const labels = wrap?.querySelectorAll('svg text').length ?? 0;
  return `zoom ${z}×  →  tier "${tier}"  (${labels} text nodes)`;
}

const btn = { padding: '5px 12px', borderRadius: '6px', border: '1px solid rgba(127,127,127,.4)',
  background: 'transparent', color: 'inherit', cursor: 'pointer', font: 'inherit' };

/** Level-of-detail: the tier the renderer draws is a pure function of zoom.
 *  high → medium → sketch → low, both in getQualityState().tier and in the
 *  amount of text that reaches the DOM. */
export default component$(() => {
  const wrap = useSignal<HTMLElement>();
  const inst = useSignal<NoSerialize<DiagramInstance>>();
  const readout = useSignal('');
  const zoom = $((z: number) => {
    if (inst.value) readout.value = tierAt(inst.value, wrap.value, z);
  });

  return (
    <div ref={wrap} style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <div style={{ display: 'flex', gap: '8px', padding: '10px 24px', borderBottom: '1px solid rgba(127,127,127,.25)', alignItems: 'center' }}>
        <span>zoom:</span>
        <button style={btn} onClick$={() => zoom(1.5)}>1.5× high</button>
        <button style={btn} onClick$={() => zoom(0.7)}>0.7× medium</button>
        <button style={btn} onClick$={() => zoom(0.3)}>0.3× sketch</button>
        <button style={btn} onClick$={() => zoom(0.15)}>0.15× low</button>
        <span style={{ marginLeft: 'auto', font: '12px/1.4 ui-monospace, monospace', opacity: '0.85' }}>{readout.value}</span>
      </div>
      <div style={{ flex: '1' }}>
        <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} rendererConfig={{ qualityGovernor: false }}
          onInit$={$((instance: DiagramInstance) => {
            inst.value = noSerialize(instance);
            instance.fitView(40);
            readout.value = tierAt(instance, wrap.value, 1.5);
            markReady();
          })} />
      </div>
    </div>
  );
});

