import { component$, $, useSignal } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { SnapController } from '@grafloria/element';
import { markReady } from '../ready';

const nodes = [
  { id: 'anchor', position: { x: 200, y: 120 }, size: { width: 120, height: 60 }, label: 'anchor' },
  { id: 'below',  position: { x: 200, y: 320 }, size: { width: 120, height: 60 }, label: 'below' },
  { id: 'mover',  position: { x: 460, y: 500 }, size: { width: 120, height: 60 }, label: 'drag me' },
];

/** Snaplines: drag a node near another's edge and its position snaps into
 *  alignment with a dashed guide. The page flips enableHelperLines; the pure
 *  SnapController.computeSnap is the engine behind the live drag path. */
export default component$(() => {
  const readout = useSignal('');
  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <div style={{ padding: '8px 24px', font: '12px/1.5 ui-monospace, monospace', opacity: '0.8',
        borderBottom: '1px solid rgba(127,127,127,.25)', whiteSpace: 'pre' }}>{readout.value}</div>
      <div style={{ flex: '1' }}>
        <GrafloriaFlow defaultNodes={nodes} defaultEdges={[]} onInit$={$((instance: DiagramInstance) => {
          // SnapController proves the engine; enableHelperLines wires it into the drag.
          new SnapController({ snapThreshold: 8, equalSpacing: true });
          instance.getEngine().setInteractionConfig({ enableHelperLines: true } as never);
          readout.value = 'drag the lower-right node toward the others — dashed guides appear as edges align';
          markReady();
        })} />
      </div>
    </div>
  );
});

interaction/keyboard-a11y.text:
import { component$, $, useSignal } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { Replica } from '@grafloria/element';
import { markReady } from '../ready';

/* eslint-disable @typescript-eslint/no-explicit-any */
const nodes = ['ingest', 'clean', 'model', 'serve'].map((id, i) => ({
  id, position: { x: 80 + i * 200, y: 160 }, size: { width: 140, height: 56 }, label: id,
}));
const edges = [
  { id: 'e1', source: 'ingest', target: 'clean' },
  { id: 'e2', source: 'clean', target: 'model' },
];
const STEP = 16;

interface OutlineItem { id: string; text: string }

/** The live-region mirror: one sentence per node, with its outgoing links. */
function outlineOf(model: any): OutlineItem[] {
  return model.getNodes().map((n: any) => {
    const outs = model.getLinks().filter((l: any) => l.sourceNodeId === n.id).map((l: any) => l.targetNodeId);
    const label = n.getMetadata('label') ?? n.id;
    return { id: n.id, text: `${label} at ${Math.round(n.position.x)},${Math.round(n.position.y)}${outs.length ? ' → connects to ' + outs.join(', ') : ''}` };
  });
}

/** Everything by keyboard: Tab moves a focus ring, arrows nudge (⌘Z undoes to
 *  the exact pixel), C+Tab+Enter connects, and a live-region outline mirror
 *  narrates the whole graph to a screen reader. Built on the public model. */
export default component$(() => {
  const kbd = useSignal<HTMLElement>();
  const readout = useSignal('');
  const active = useSignal('');
  const outline = useSignal<OutlineItem[]>([]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <div style={{ padding: '8px 24px', font: '12px/1.5 ui-monospace, monospace', opacity: '0.85',
        borderBottom: '1px solid rgba(127,127,127,.25)', whiteSpace: 'pre' }}>{readout.value}</div>
      <div style={{ position: 'relative', flex: '1' }}>
        <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} style={{ height: '100%' }} onInit$={$((instance: DiagramInstance) => {
          const api = instance as any;
          const model = api.getModel();
          const replica = new Replica(model, { actor: 'kbd', onLocalOp: () => {} });
          const order = () => model.getNodes().map((n: any) => n.id).sort();
          const state = { focusIndex: 0, connectFrom: null as string | null };
          const focusedId = () => order()[state.focusIndex];

          const paintFocus = () => {
            const id = focusedId();
            active.value = `node-${id}`;
            for (const n of model.getNodes()) n.setSelected(n.id === id);
            api.renderNow();
          };
          const syncOutline = () => { outline.value = outlineOf(model); };
          const report = (m: string) => {
            readout.value = `focused: ${focusedId()}${state.connectFrom ? `  connecting from ${state.connectFrom}` : ''}\n${m}`;
          };

          const handleKey = (key: string, shift = false, meta = false) => {
            const ids = order();
            if (key === 'Tab') { state.focusIndex = (state.focusIndex + (shift ? -1 : 1) + ids.length) % ids.length; paintFocus(); report('Tab moved focus'); return; }
            if (key === 'z' && meta) { replica.undo(); api.renderNow(); syncOutline(); report('⌘Z undo'); return; }
            if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(key)) {
              const n = model.getNode(focusedId());
              const dx = key === 'ArrowLeft' ? -STEP : key === 'ArrowRight' ? STEP : 0;
              const dy = key === 'ArrowUp' ? -STEP : key === 'ArrowDown' ? STEP : 0;
              n.setPosition(n.position.x + dx, n.position.y + dy);
              api.renderNow(); syncOutline(); report(`nudged ${key.replace('Arrow', '').toLowerCase()}`);
              return;
            }
            if (key === 'c') { state.connectFrom = focusedId(); report('connect mode: Tab to a target, Enter to link'); return; }
            if (key === 'Enter' && state.connectFrom) {
              const target = focusedId();
              if (target !== state.connectFrom) {
                const s = model.getNode(state.connectFrom).getPortBySide('right');
                const t = model.getNode(target).getPortBySide('left');
                const csm = instance.getEngine().getConnectionStateManager() as any;
                csm.startConnection(s, { x: 0, y: 0 });
                csm.completeConnection(t);
              }
              state.connectFrom = null;
              api.renderNow(); syncOutline(); report('linked by keyboard');
              return;
            }
          };
          // Tab must be stopped synchronously, so this is a plain DOM listener.
          kbd.value!.addEventListener('keydown', (e) => {
            const handledKeys = ['Tab', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Enter', 'c', 'z'];
            if (handledKeys.includes(e.key)) { e.preventDefault(); handleKey(e.key, e.shiftKey, e.metaKey || e.ctrlKey); }
          });
          api.on('connect', () => syncOutline());
          api.on('edges:change', () => syncOutline());
          api.on('nodes:change', () => syncOutline());

          paintFocus();
          syncOutline();
          report('ready — keyboard only');
          markReady();
        })} />
        <div ref={kbd} tabIndex={0} role="application"
          aria-label="Diagram editor. Tab to move between nodes, arrow keys to nudge, C then a node to connect."
          aria-activedescendant={active.value}
          style={{ position: 'absolute', inset: '0', outline: 'none' }} />
        <ul role="list" aria-live="polite" aria-label="Diagram outline"
          style={{ position: 'absolute', width: '1px', height: '1px', overflow: 'hidden', clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap' }}>
          {outline.value.map((it) => <li key={it.id} id={`node-${it.id}`} role="listitem">{it.text}</li>)}
        </ul>
        <div style={{ position: 'absolute', left: '12px', bottom: '10px', font: '12px system-ui', opacity: '0.6' }}>
          Tab / ⇧Tab · arrows nudge · ⌘Z undo · C+Tab+Enter connect
        </div>
      </div>
    </div>
  );
});

interaction/marquee-select.text:
import { component$, $, noSerialize, useSignal, useVisibleTask$, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { registerTool } from '@grafloria/element';
import { markReady } from '../ready';

/* eslint-disable @typescript-eslint/no-explicit-any */
const nodes = [
  { id: 'n1', position: { x: 120, y: 110 }, size: { width: 120, height: 60 }, label: 'n1' },
  { id: 'n2', position: { x: 300, y: 110 }, size: { width: 120, height: 60 }, label: 'n2' },
  { id: 'n3', position: { x: 120, y: 230 }, size: { width: 120, height: 60 }, label: 'n3' },
  { id: 'n4', position: { x: 560, y: 120 }, size: { width: 120, height: 60 }, label: 'n4' },
  { id: 'n5', position: { x: 560, y: 300 }, size: { width: 120, height: 60 }, label: 'n5' },
  { id: 'n6', position: { x: 330, y: 410 }, size: { width: 120, height: 60 }, label: 'n6' },
];
const edges = [
  { id: 'e1', source: 'n1', target: 'n2' },
  { id: 'e2', source: 'n1', target: 'n3' },
  { id: 'e3', source: 'n4', target: 'n5' },
];

function worldBounds(node: any) {
  const p = typeof node.getWorldPosition === 'function' ? node.getWorldPosition() : node.position;
  return { x: p.x, y: p.y, w: node.size.width, h: node.size.height };
}
function nodesInRect(model: any, rect: any) {
  const x1 = Math.min(rect.ax, rect.bx), y1 = Math.min(rect.ay, rect.by);
  const x2 = Math.max(rect.ax, rect.bx), y2 = Math.max(rect.ay, rect.by);
  return model.getNodes().filter((n: any) => {
    const b = worldBounds(n);
    return b.x >= x1 && b.y >= y1 && b.x + b.w <= x2 && b.y + b.h <= y2;
  });
}

/** Marquee (rubber-band) box-selection — the gesture the binder leaves to the
 *  host — assembled from the public registerTool + viewport + selection seams.
 *  Shift adds to the selection. */
export default component$(() => {
  const wrap = useSignal<HTMLElement>();
  const dispose = useSignal<NoSerialize<() => void>>();

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    cleanup(() => dispose.value?.());
  }, { strategy: 'document-ready' });

  return (
    <div ref={wrap} style={{ height: '100vh', position: 'relative' }}>
      <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} onInit$={$((instance: DiagramInstance) => {
        const host = wrap.value!;
        const api = instance as any;
        const model = api.getModel();

        let overlay: HTMLDivElement | null = null;
        let start: any = null;
        let baseSelection = new Set<string>();

        const showBox = (aScreen: any, bScreen: any) => {
          if (!overlay) {
            overlay = document.createElement('div');
            overlay.className = 'marquee-box';
            overlay.style.cssText = 'position:absolute;pointer-events:none;z-index:20;border:1px dashed #3b82f6;background:rgba(59,130,246,.15);border-radius:2px;';
            host.appendChild(overlay);
          }
          const x = Math.min(aScreen.x, bScreen.x), y = Math.min(aScreen.y, bScreen.y);
          overlay.style.left = x + 'px'; overlay.style.top = y + 'px';
          overlay.style.width = Math.abs(bScreen.x - aScreen.x) + 'px';
          overlay.style.height = Math.abs(bScreen.y - aScreen.y) + 'px';
        };
        const clearBox = () => { overlay?.remove(); overlay = null; };
        const applySelection = (worldRect: any, additive: boolean) => {
          const hit = new Set(nodesInRect(model, worldRect).map((n: any) => n.id));
          for (const n of model.getNodes()) n.setSelected(hit.has(n.id) || (additive && baseSelection.has(n.id)));
          api.renderNow();
        };

        dispose.value = noSerialize(registerTool({
          id: 'marquee',
          priority: 1,
          hitTest: (_ev: any, hit: any) => !!hit.empty,
          onPointerDown: (ev: any) => {
            start = { world: { ...ev.world }, screen: { ...ev.screen } };
            const additive = ev.modifiers.shift || ev.modifiers.ctrl || ev.modifiers.meta;
            baseSelection = new Set(model.getSelectedNodes().map((n: any) => n.id));
            if (!additive) { model.clearSelection(); baseSelection.clear(); }
          },
          onPointerMove: (ev: any) => {
            if (!start) return;
            showBox(start.screen, ev.screen);
            const additive = ev.modifiers.shift || ev.modifiers.ctrl || ev.modifiers.meta;
            applySelection({ ax: start.world.x, ay: start.world.y, bx: ev.world.x, by: ev.world.y }, additive);
          },
          onPointerUp: (ev: any) => {
            if (start) {
              const additive = ev.modifiers.shift || ev.modifiers.ctrl || ev.modifiers.meta;
              applySelection({ ax: start.world.x, ay: start.world.y, bx: ev.world.x, by: ev.world.y }, additive);
            }
            start = null; clearBox();
          },
          onCancel: () => { start = null; clearBox(); },
        } as any) as unknown as () => void);
        markReady();
      })} />
    </div>
  );
});

interaction/parent-move.text:
import { component$, $ } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { markReady } from '../ready';

