whiteboard/stroke-edit.text:
import { component$, $, noSerialize, useSignal, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { registerTool, createDrawTool, createStrokeEditTool, StrokeModel } from '@grafloria/element';
import { markReady } from '../ready';
import { whiteboardHost } from './whiteboard-host';

/** Stroke edit: draw ink with the pen, then switch to the edit tool and drag a
 *  committed stroke — the whole stroke translates as one undoable step. The
 *  draw and edit tools are both registered; the toolbar is the tool-switch
 *  seam (setActive). */
type Tool = { setActive: (a: boolean) => void };

const tab = (active: boolean) => ({
  padding: '4px 12px', borderRadius: '6px', border: '1px solid rgba(127,127,127,.4)', cursor: 'pointer', font: 'inherit',
  background: active ? '#0f766e' : 'transparent', color: active ? '#fff' : 'inherit',
});

export default component$(() => {
  const hostRef = useSignal<HTMLDivElement>();
  // The tools are live gesture handlers, not data.
  const drawTool = useSignal<NoSerialize<Tool>>();
  const editTool = useSignal<NoSerialize<Tool>>();
  const edit = useSignal(false);

  return (
    <div>
      <div style={{ display: 'flex', gap: '8px', padding: '10px 24px', borderBottom: '1px solid rgba(127,127,127,.25)', alignItems: 'center' }}>
        <span>tool:</span>
        <button style={tab(!edit.value)} onClick$={() => {
          edit.value = false;
          drawTool.value?.setActive(true);
          editTool.value?.setActive(false);
        }}>draw</button>
        <button style={tab(edit.value)} onClick$={() => {
          edit.value = true;
          drawTool.value?.setActive(false);
          editTool.value?.setActive(true);
        }}>edit</button>
      </div>
      <div ref={hostRef} style={{ display: 'block', height: 'calc(100vh - 45px)' }}>
        <GrafloriaFlow defaultNodes={[]} defaultEdges={[]} style={{ display: 'block', height: '100%' }}
          onInit$={$((instance: DiagramInstance) => {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const model = instance.getModel() as any;
            if (model) {
              model.addStroke(new StrokeModel(
                [{ x: 120, y: 200 }, { x: 240, y: 230 }, { x: 360, y: 210 }, { x: 420, y: 260 }],
                { color: '#0f766e', width: 4 }, { id: 'seed' },
              ));
              const wbHost = whiteboardHost(instance, hostRef.value!);
              const draw = createDrawTool(wbHost, { color: '#0f766e', width: 4 }) as unknown as Tool;
              registerTool(draw as never);
              const editor = createStrokeEditTool(wbHost, { active: false }) as unknown as Tool;
              registerTool(editor as never);
              drawTool.value = noSerialize(draw);
              editTool.value = noSerialize(editor);
              instance.renderNow();
            }
            markReady();
          })} />
      </div>
    </div>
  );
});

misc/download-image.text:
import { component$, $, noSerialize, useSignal, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, type DiagramInstance } from '@grafloria/qwik';
import { markReady } from '../ready';

/** Download image: exports the VNode tree — labels, arrowheads, shadows and all
 *  — not a screenshot. PNG (raster) and SVG (vector) both come from the same
 *  instance.export() pipeline. */
const SHADOW = { offsetX: 3, offsetY: 4, blur: 5, color: '#1e293b' };

const nodes = [
  { id: 'ingest',    label: 'Ingest',    position: { x: 60,  y: 100 }, size: { width: 170, height: 78 }, style: { fill: '#dbeafe', stroke: '#2563eb', strokeWidth: 2 } },
  { id: 'transform', label: 'Transform', position: { x: 340, y: 100 }, size: { width: 170, height: 78 }, style: { fill: '#ffffff', stroke: '#0f172a', strokeWidth: 2, shadow: SHADOW } },
  { id: 'publish',   label: 'Publish',   position: { x: 620, y: 100 }, size: { width: 170, height: 78 }, style: { fill: '#dcfce7', stroke: '#16a34a', strokeWidth: 2 } },
];
const edges = [
  { id: 'e1', source: 'ingest', target: 'transform', label: 'rows' },
  { id: 'e2', source: 'transform', target: 'publish' },
];

function download(href: string, name: string) {
  const a = document.createElement('a');
  a.href = href; a.download = name; a.click();
}

const btn = { padding: '6px 14px', borderRadius: '6px', border: '1px solid rgba(127,127,127,.4)', background: 'transparent', color: 'inherit', cursor: 'pointer', font: 'inherit' };

export default component$(() => {
  const instance = useSignal<NoSerialize<DiagramInstance>>();
  const note = useSignal('Exports the VNode tree — not a screenshot.');

  return (
    <div>
      <div style={{ display: 'flex', gap: '8px', alignItems: 'center', padding: '10px 24px', borderBottom: '1px solid rgba(127,127,127,.25)', flexWrap: 'wrap' }}>
        <button style={btn} onClick$={async () => {
          const d = await instance.value!.export('png', { scale: 2 });
          download(d, 'diagram.png');
          note.value = `diagram.png saved (${Math.round(d.length * 3 / 4 / 1024)} KB)`;
        }}>download PNG</button>
        <button style={btn} onClick$={async () => {
          const svg = await instance.value!.export('svg');
          download('data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg), 'diagram.svg');
          note.value = `diagram.svg saved (${Math.round(svg.length / 1024)} KB)`;
        }}>download SVG</button>
        <span style={{ font: '12px ui-monospace,monospace', opacity: '.8' }}>{note.value}</span>
      </div>
      <GrafloriaFlow
        defaultNodes={nodes}
        defaultEdges={edges}
        style={{ display: 'block', height: 'calc(100vh - 45px)' }}
        onInit$={$((api: DiagramInstance) => { instance.value = noSerialize(api); markReady(); })}
      />
    </div>
  );
});

